SELECT product_id, product_name, sku, current_stock, safety_stock, stock_value, unit, status, nearest_expiry_date
FROM agent_v3_product_inventory_view
WHERE agent_v3_product_inventory_view.store_id = ANY(:allowedStoreIds) AND (current_stock < safety_stock) LIMIT 100;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (staff_id = 42) LIMIT 100;

SELECT COUNT(DISTINCT staff_id) AS staff_count
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (status = '***') LIMIT 1;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (staff_id = 41) LIMIT 100;
